        sufficient = record_outcome(sufficient, i % 2)
        i = i + 1
    }
    sufficient = compute_variety(sufficient)
    assert(has_requisite_variety(sufficient))
    let def1 = variety_deficit(sufficient)
    assert(def1 >= 0.0)
    println("  8 reg vs 6 env, 2 outcomes: requisite=true, deficit >= 0 ✓")

    // Insufficient: 3 reg states vs 6 env states, 2 outcomes
    var insufficient = variety_new()
    i = 0
    while i < 100 {
        insufficient = record_env_state(insufficient, i % 6)
        insufficient = record_reg_state(insufficient, i % 3)
        insufficient = record_outcome(insufficient, i % 2)
        i = i + 1
    }
    insufficient = compute_variety(insufficient)
    assert(!has_requisite_variety(insufficient))
    let def2 = variety_deficit(insufficient)
    assert(def2 < 0.0)
    println("  3 reg vs 6 env, 2 outcomes: requisite=false, deficit < 0 ✓")

    println("  PROOF 7: PASS")
    println("")
