fn make_3x3(
    a00: f64, a01: f64, a02: f64,
    a10: f64, a11: f64, a12: f64,
    a20: f64, a21: f64, a22: f64
) -> MatNM with Mut {
    var m = matnm_zeros(3, 3)
    m = matnm_set(m, 0, 0, a00)
    m = matnm_set(m, 0, 1, a01)
    m = matnm_set(m, 0, 2, a02)
    m = matnm_set(m, 1, 0, a10)
    m = matnm_set(m, 1, 1, a11)
    m = matnm_set(m, 1, 2, a12)
    m = matnm_set(m, 2, 0, a20)
    m = matnm_set(m, 2, 1, a21)
    m = matnm_set(m, 2, 2, a22)
    return m
}

