//@ run-pass
// PBPK Validation: 2-compartment Euler model vs analytical Bateman equation
//
// Model: Dose → Gut (absorption) → Central (elimination)
//   dGut/dt     = -ka * Gut
//   dCentral/dt = ka * Gut - ke * Central
//
// Analytical (Bateman equation):
//   Gut(t)     = Dose * exp(-ka * t)
//   Central(t) = Dose * ka / (ka - ke) * (exp(-ke * t) - exp(-ka * t))
//   AUC(0→∞)   = Dose / ke  (for complete absorption)
//
// Parameters: Dose=500mg, ka=1.0/h, ke=0.1/h, dt=0.1h, 240 steps (24h)

struct PBPKState {
    t: f64,
    gut: f64,
    central: f64,
    auc: f64,
    cmax: f64,
    tmax: f64
}

fn euler_step(s: PBPKState, dt: f64) -> PBPKState {
    let ka = 1.0
    let ke = 0.1
    let d_gut = -ka * s.gut
    let d_central = ka * s.gut - ke * s.central
    let new_central = s.central + d_central * dt

    // Track Cmax/Tmax
    let new_t = s.t + dt
    var cmax = s.cmax
    var tmax = s.tmax
    if new_central > s.cmax {
        cmax = new_central
        tmax = new_t
    }

    PBPKState {
        t: new_t,
        gut: s.gut + d_gut * dt,
        central: new_central,
        auc: s.auc + s.central * dt,
        cmax: cmax,
        tmax: tmax
    }
}

fn main() -> i32 with IO, Div, Mut {
    var s = PBPKState {
        t: 0.0, gut: 500.0, central: 0.0,
        auc: 0.0, cmax: 0.0, tmax: 0.0
    }
    let dt = 0.1
    var i = 0

    while i < 240 {
        s = euler_step(s, dt)
        i = i + 1
    }

    // Print results for validation
    println(s.t)
    println(s.gut)
    println(s.central)
    println(s.auc)
    println(s.cmax)
    println(s.tmax)

    // Validate against analytical expectations:
    //
    // 1. Time should be 24.0h
    if s.t < 23.9 { return 1 }
    if s.t > 24.1 { return 2 }

    // 2. Gut should be ~0 (exp(-24) ≈ 1.9e-11)
    if s.gut > 0.01 { return 3 }

    // 3. Central: Bateman at t=24h
    //    C(24) = 500 * 1.0/(1.0-0.1) * (exp(-0.1*24) - exp(-1.0*24))
    //          = 555.56 * (exp(-2.4) - exp(-24))
    //          = 555.56 * (0.0907 - ~0)
    //          = ~50.4 mg
    //    Euler with dt=0.1 will be close but not exact
    if s.central < 30.0 { return 4 }
    if s.central > 70.0 { return 5 }

    // 4. AUC should be substantial (analytical AUC_0-inf = Dose/ke = 5000)
    //    But we only integrate to 24h, so expect ~4000-5000
    if s.auc < 3000.0 { return 6 }
    if s.auc > 6000.0 { return 7 }

    // 5. Cmax should be ~200-300 mg (depends on ka/ke ratio)
    //    Analytical Cmax at tmax = ln(ka/ke)/(ka-ke) = ln(10)/0.9 ≈ 2.56h
    //    Cmax = 500*(1.0/0.9)*(0.1^(0.1/0.9) - 0.1^(1.0/0.9))
    //    Euler approximation: should be in ballpark
    if s.cmax < 100.0 { return 8 }
    if s.cmax > 400.0 { return 9 }

    // 6. Tmax should be near 2.56h (analytical)
    if s.tmax < 1.5 { return 10 }
    if s.tmax > 4.0 { return 11 }

    return 0
}

//@ run-pass
// PBPK Validation: 3-compartment RK2 model with higher-order accuracy
//
// Model: Gut → Liver (first-pass) → Central (elimination)
//   dGut/dt     = -ka * Gut
//   dLiver/dt   = ka * Gut * fa - (Q_h/V_h) * Liver - CL_h * Liver
//   dCentral/dt = (Q_h/V_h) * Liver - ke * Central
//
// Uses RK2 (midpoint method) for 2nd-order accuracy
// Parameters: Dose=500mg, ka=1.0/h, ke=0.1/h, dt=0.05h, 480 steps (24h)

struct Conc {
    gut: f64,
    liver: f64,
    central: f64
}

struct SimState {
    state: Conc,
    t: f64,
    auc: f64,
    cmax: f64,
    tmax: f64
}

fn derivatives(s: Conc) -> Conc {
    let ka = 1.0
    let fa = 0.8
    let q_h = 0.5
    let cl_h = 0.3
    let ke = 0.1
    Conc {
        gut: -ka * s.gut,
        liver: ka * s.gut * fa - q_h * s.liver - cl_h * s.liver,
        central: q_h * s.liver - ke * s.central
    }
}

fn rk2_step(s: Conc, dt: f64) -> Conc {
    // k1 = f(y_n)
    let k1 = derivatives(s)

    // midpoint: y_mid = y_n + 0.5*dt*k1
    let mid = Conc {
        gut: s.gut + 0.5 * dt * k1.gut,
        liver: s.liver + 0.5 * dt * k1.liver,
        central: s.central + 0.5 * dt * k1.central
    }

    // k2 = f(y_mid)
    let k2 = derivatives(mid)

    // y_{n+1} = y_n + dt * k2
    Conc {
        gut: s.gut + dt * k2.gut,
        liver: s.liver + dt * k2.liver,
        central: s.central + dt * k2.central
    }
}

fn main() -> i32 with IO, Div, Mut {
    var sim = SimState {
        state: Conc { gut: 500.0, liver: 0.0, central: 0.0 },
        t: 0.0, auc: 0.0, cmax: 0.0, tmax: 0.0
    }
    let dt = 0.05
    var i = 0

    while i < 480 {
        let new_state = rk2_step(sim.state, dt)
        let new_t = sim.t + dt

        // Trapezoidal AUC
        let auc_increment = 0.5 * (sim.state.central + new_state.central) * dt

        var cmax = sim.cmax
        var tmax = sim.tmax
        if new_state.central > sim.cmax {
            cmax = new_state.central
            tmax = new_t
        }

        sim = SimState {
            state: new_state,
            t: new_t,
            auc: sim.auc + auc_increment,
            cmax: cmax,
            tmax: tmax
        }
        i = i + 1
    }

    // Print results
    println(sim.t)
    println(sim.state.gut)
    println(sim.state.liver)
    println(sim.state.central)
    println(sim.auc)
    println(sim.cmax)
    println(sim.tmax)

    // Validate:
    // 1. Time = 24.0h
    if sim.t < 23.9 { return 1 }

    // 2. Gut fully absorbed (exp(-24) ≈ 0)
    if sim.state.gut > 0.01 { return 2 }

    // 3. AUC should be positive and substantial
    if sim.auc < 100.0 { return 3 }

    // 4. Cmax > 0 (drug reached central compartment)
    if sim.cmax < 10.0 { return 4 }

    // 5. Tmax in physiological range (1-8h for oral absorption)
    if sim.tmax < 0.5 { return 5 }
    if sim.tmax > 12.0 { return 6 }

    // 6. All concentrations non-negative (conservation of mass)
    if sim.state.gut < 0.0 { return 7 }
    if sim.state.liver < 0.0 { return 8 }
    if sim.state.central < 0.0 { return 9 }

    // 7. 480 iterations completed
    if i != 480 { return 10 }

    return 0
}

//@ run-pass
// PK Domain Uncertainty Plugin Test Suite
//
// Validates WS2 Track 5 — PK-specific uncertainty analysis:
//   1.  Clearance dominance detection (CL contributes >70%)
//   2.  Volume dominance detection (V contributes most)
//   3.  Balanced contributions (no single dominant)
//   4.  SCr as proxy for clearance (Cockcroft-Gault scenario)
//   5.  Sensitivity index S_Ti > 0.7 triggers clearance dominance flag
//   6.  PK recommendations: clearance dominant -> TDM
//   7.  PK recommendations: absorption dominant -> bioequivalence
//   8.  Clinical significance: uncertainty > therapeutic window
//   9.  Clinical significance: uncertainty < therapeutic window
//  10.  Edge case: single parameter is 100% dominant
//  11.  Recommendation for SCr dominant -> cystatin C
//  12.  Sensitivity indices sum to 1.0
//
// Reference: Saltelli et al. (2008), FDA PopPK Guidance (2022)

// ============================================================================
// HELPERS (self-contained, no imports)
// ============================================================================

fn abs_val(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn sqrt_val(x: f64) -> f64 {
    if x <= 0.0 { return 0.0 }
    var guess = x / 2.0
    if guess < 0.001 { guess = 0.001 }
    var i = 0
    while i < 30 {
        guess = (guess + x / guess) / 2.0
        i = i + 1
    }
    return guess
}

fn max_val(a: f64, b: f64) -> f64 {
    if a > b { return a }
    return b
}

fn min_val(a: f64, b: f64) -> f64 {
    if a < b { return a }
    return b
}

