    println(at_10)
    print("  AT[0,1]=")
    println(at_01)

    let ok_inv = err < 1e-12
    let ok_vals = abs_f64(at_10 - 2.0) < 1e-12 && abs_f64(at_01 - 3.0) < 1e-12

    return ok_inv && ok_vals
}

