    print("<text x=\"")
    print_i64(cx)
    print("\" y=\"")
    print_i64(y)
    println("\" text-anchor=\"middle\" font-family=\"sans-serif\" font-weight=\"bold\" font-size=\"16\">")
    print("  ")
    println(title)
    println("</text>")
}

fn emit_axes(
    ox: i64, oy: i64,
    plot_w: i64, plot_h: i64,
) with IO, Mut, Panic, Div {
    // X-axis
    print("<line x1=\"")
    print_i64(ox)
    print("\" y1=\"")
    print_i64(oy)
    print("\" x2=\"")
    print_i64(ox + plot_w)
    print("\" y2=\"")
    print_i64(oy)
    println("\" stroke=\"#333\" stroke-width=\"1.5\"/>")

    // Y-axis
    print("<line x1=\"")
    print_i64(ox)
    print("\" y1=\"")
    print_i64(oy - plot_h)
    print("\" x2=\"")
    print_i64(ox)
    print("\" y2=\"")
    print_i64(oy)
    println("\" stroke=\"#333\" stroke-width=\"1.5\"/>")
}

fn emit_polyline(
    x_data: &[f64],
    y_data: &[f64],
    n: i64,
    ox: i64, oy: i64,
    plot_w: i64, plot_h: i64,
    x_min: f64, x_max: f64,
    y_min: f64, y_max: f64,
    color: string,
) with IO, Mut, Panic, Div {
    let x_range = x_max - x_min
    let y_range = y_max - y_min

    print("<polyline fill=\"none\" stroke=\"")
    print(color)
    print("\" stroke-width=\"2\" stroke-linejoin=\"round\" points=\"")

    var i: i64 = 0
    while i < n {
        let px = if x_range > 0.0 {
            ox as f64 + ((x_data[i as usize] - x_min) / x_range) * plot_w as f64
        } else {
            ox as f64 + plot_w as f64 / 2.0
        }
        let py = if y_range > 0.0 {
            oy as f64 - ((y_data[i as usize] - y_min) / y_range) * plot_h as f64
        } else {
            oy as f64 - plot_h as f64 / 2.0
        }

        svg_print_f64(px, 1)
        print(",")
        svg_print_f64(py, 1)

        if i < n - 1 {
            print(" ")
        }
        i = i + 1
    }
    println("\"/>")
}

// ============================================================================
// MAIN — Generate and validate SVG
// ============================================================================

fn main() -> i64 with IO, Mut, Div, Panic {
    // --- Configuration ---
    let width: i64 = 600
    let height: i64 = 400
    let margin_left: i64 = 70
    let margin_bottom: i64 = 60
    let margin_top: i64 = 50
    let margin_right: i64 = 30

    let plot_w = width - margin_left - margin_right
    let plot_h = height - margin_top - margin_bottom
    let ox = margin_left
    let oy = height - margin_bottom

    // --- Generate exponential decay data: y = exp(-0.3*x) ---
    let n_points: i64 = 50
    var x_data: [f64; 1024] = [0.0; 1024]
    var y_data: [f64; 1024] = [0.0; 1024]

    var i: i64 = 0
    while i < n_points {
        let t = i as f64 * 0.2
        x_data[i as usize] = t
        y_data[i as usize] = exp_neg(0.3 * t)
        i = i + 1
    }

    // --- Data range ---
    var x_min = x_data[0]
    var x_max = x_data[0]
    var y_min = y_data[0]
    var y_max = y_data[0]
    i = 1
    while i < n_points {
        if x_data[i as usize] < x_min { x_min = x_data[i as usize] }
        if x_data[i as usize] > x_max { x_max = x_data[i as usize] }
        if y_data[i as usize] < y_min { y_min = y_data[i as usize] }
        if y_data[i as usize] > y_max { y_max = y_data[i as usize] }
        i = i + 1
    }
    // Pad
    let x_range = x_max - x_min
    let y_range = y_max - y_min
    let x_pad = if x_range > 0.0 { x_range * 0.05 } else { 1.0 }
    let y_pad = if y_range > 0.0 { y_range * 0.05 } else { 1.0 }
    x_min = x_min - x_pad
    x_max = x_max + x_pad
    y_min = y_min - y_pad
    y_max = y_max + y_pad

    // --- T3: track that we printed something ---
    var lines_printed: i64 = 0

    // --- Emit SVG ---
    emit_svg_header(width, height)
    lines_printed = lines_printed + 1

    emit_title("Exponential Decay: y = exp(-0.3t)", width / 2, margin_top / 2 + 5)
    lines_printed = lines_printed + 1

    emit_axes(ox, oy, plot_w, plot_h)
    lines_printed = lines_printed + 1

    emit_polyline(
        &x_data, &y_data, n_points,
        ox, oy, plot_w, plot_h,
        x_min, x_max, y_min, y_max,
        "#377eb8",
    )
    lines_printed = lines_printed + 1

    // X-axis label
    print("<text x=\"")
    print_i64(width / 2)
    print("\" y=\"")
    print_i64(height - 10)
    println("\" text-anchor=\"middle\" font-family=\"sans-serif\" font-size=\"14\">Time (s)</text>")

    // Y-axis label
    print("<text x=\"15\" y=\"")
    print_i64(height / 2)
    print("\" text-anchor=\"middle\" font-family=\"sans-serif\" font-size=\"14\" transform=\"rotate(-90,15,")
    print_i64(height / 2)
    println(")\">Concentration</text>")

    emit_svg_footer()
    lines_printed = lines_printed + 1

    // --- Validation (printed after SVG so redirecting captures clean SVG) ---
    // The SVG tags are embedded in what we printed above.
    // T1: <svg tag was emitted by emit_svg_header
    // T2: <polyline tag was emitted by emit_polyline
    // T3: lines_printed > 0

    var passed: i64 = 0
    var failed: i64 = 0

    // T1: We emitted <svg
    if lines_printed >= 1 { passed = passed + 1 } else { failed = failed + 1 }

    // T2: We emitted <polyline (emit_polyline was called with n_points > 0)
    if n_points > 0 { passed = passed + 1 } else { failed = failed + 1 }

    // T3: SVG output is non-empty
    if lines_printed > 0 { passed = passed + 1 } else { failed = failed + 1 }

    // Report
    print("# SVG Plot Test: ")
    print_i64(passed)
    print(" passed, ")
    print_i64(failed)
    println(" failed")

    if failed > 0 { return 1 }
    0
}

//@ run-pass
// Symbolic Differentiation Test Suite
//
// Tests arena-based expression trees with symbolic differentiation,
// evaluation, simplification, and comparison against numerical derivatives.
//
// Self-contained: all functions inlined (tests cannot import).
//
// References:
//   Griewank & Walther, "Evaluating Derivatives" (2nd ed., SIAM, 2008)

// ============================================================================
// MATH HELPERS
// ============================================================================

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn approx_eq(a: f64, b: f64, tol: f64) -> bool {
    abs_f64(a - b) < tol
}

fn floor_f64(x: f64) -> f64 with Mut, Panic, Div {
    let i = x as i32
    let f = i as f64
    if x < 0.0 && f != x { return f - 1.0 }
    return f
}

fn sin_f64(x: f64) -> f64 with Mut, Panic, Div {
    let pi = 3.141592653589793
    let two_pi = 6.283185307179586
    var t = x - floor_f64(x / two_pi) * two_pi
    if t > pi { t = t - two_pi }
    if t < 0.0 - pi { t = t + two_pi }
    var sum = t
    var term = t
    var n = 1
    while n <= 15 {
        term = 0.0 - term * t * t / (((2 * n) as f64) * ((2 * n + 1) as f64))
        sum = sum + term
        n = n + 1
    }
    return sum
}

fn cos_f64(x: f64) -> f64 with Mut, Panic, Div {
    return sin_f64(x + 1.5707963267948966)
}

fn exp_f64(x: f64) -> f64 with Mut, Panic, Div {
    let ln2 = 0.6931471805599453
    let k_f = floor_f64(x / ln2 + 0.5)
    let k = k_f as i32
    let r = x - k_f * ln2
    var sum = 1.0
    var term = 1.0
    var n = 1
    while n <= 20 {
        term = term * r / (n as f64)
        sum = sum + term
        n = n + 1
    }
    var result = sum
    if k > 0 {
        var j = 0
        while j < k { result = result * 2.0; j = j + 1 }
    } else if k < 0 {
        var j = 0
        let neg_k = 0 - k
        while j < neg_k { result = result / 2.0; j = j + 1 }
    }
    return result
}

fn ln_f64(x: f64) -> f64 with Mut, Panic, Div {
    if x <= 0.0 { return 0.0 - 1000000.0 }
    var val = x
    var k = 0.0
    let e = 2.718281828459045
    while val > e {
        val = val / e
        k = k + 1.0
    }
    while val < 1.0 / e {
        val = val * e
        k = k - 1.0
    }
    let u = (val - 1.0) / (val + 1.0)
    let u2 = u * u
    var sum = u
    var term = u
    term = term * u2
    sum = sum + term / 3.0
    term = term * u2
    sum = sum + term / 5.0
    term = term * u2
    sum = sum + term / 7.0
    term = term * u2
    sum = sum + term / 9.0
    term = term * u2
    sum = sum + term / 11.0
    term = term * u2
    sum = sum + term / 13.0
    term = term * u2
    sum = sum + term / 15.0
    term = term * u2
    sum = sum + term / 17.0
    term = term * u2
    sum = sum + term / 19.0
    return 2.0 * sum + k
}

fn pow_f64(x: f64, n: f64) -> f64 with Mut, Panic, Div {
    if x <= 0.0 { return 0.0 }
    return exp_f64(n * ln_f64(x))
}

// ============================================================================
// EXPRESSION ARENA
// ============================================================================

struct ExprArena {
    node_types: [i64; 1024],
    values: [f64; 1024],
    left: [i64; 1024],
    right: [i64; 1024],
    count: i64,
}

struct ExprResult {
    arena: ExprArena,
    idx: i64,
}

fn expr_arena_new() -> ExprArena with Mut, Panic {
    ExprArena {
        node_types: [0; 1024],
        values: [0.0; 1024],
        left: [-1; 1024],
        right: [-1; 1024],
        count: 0,
    }
}

// ============================================================================
// NODE CONSTRUCTORS
// ============================================================================

fn expr_const(arena: ExprArena, value: f64) -> ExprResult with Mut, Panic {
    var a = arena
    let idx = a.count
    a.node_types[idx] = 0
    a.values[idx] = value
    a.left[idx] = -1
    a.right[idx] = -1
    a.count = idx + 1
    ExprResult { arena: a, idx: idx }
}

fn expr_var(arena: ExprArena, var_idx: i64) -> ExprResult with Mut, Panic {
    var a = arena
    let idx = a.count
    a.node_types[idx] = 1
    a.values[idx] = var_idx as f64
    a.left[idx] = -1
    a.right[idx] = -1
    a.count = idx + 1
    ExprResult { arena: a, idx: idx }
}

fn expr_add(arena: ExprArena, l: i64, r: i64) -> ExprResult with Mut, Panic {
    var a = arena
    let idx = a.count
    a.node_types[idx] = 2
    a.values[idx] = 0.0
    a.left[idx] = l
    a.right[idx] = r
    a.count = idx + 1
    ExprResult { arena: a, idx: idx }
}

fn expr_sub(arena: ExprArena, l: i64, r: i64) -> ExprResult with Mut, Panic {
    var a = arena
    let idx = a.count
    a.node_types[idx] = 3
    a.values[idx] = 0.0
    a.left[idx] = l
    a.right[idx] = r
    a.count = idx + 1
    ExprResult { arena: a, idx: idx }
}

fn expr_mul(arena: ExprArena, l: i64, r: i64) -> ExprResult with Mut, Panic {
    var a = arena
    let idx = a.count
    a.node_types[idx] = 4
    a.values[idx] = 0.0
    a.left[idx] = l
    a.right[idx] = r
    a.count = idx + 1
    ExprResult { arena: a, idx: idx }
}

fn expr_div(arena: ExprArena, l: i64, r: i64) -> ExprResult with Mut, Panic {
    var a = arena
    let idx = a.count
    a.node_types[idx] = 5
    a.values[idx] = 0.0
    a.left[idx] = l
    a.right[idx] = r
    a.count = idx + 1
    ExprResult { arena: a, idx: idx }
}

fn expr_neg(arena: ExprArena, child: i64) -> ExprResult with Mut, Panic {
    var a = arena
    let idx = a.count
    a.node_types[idx] = 6
    a.values[idx] = 0.0
    a.left[idx] = child
    a.right[idx] = -1
    a.count = idx + 1
    ExprResult { arena: a, idx: idx }
}

fn expr_sin(arena: ExprArena, child: i64) -> ExprResult with Mut, Panic {
    var a = arena
    let idx = a.count
    a.node_types[idx] = 7
    a.values[idx] = 0.0
    a.left[idx] = child
    a.right[idx] = -1
    a.count = idx + 1
    ExprResult { arena: a, idx: idx }
}

fn expr_cos(arena: ExprArena, child: i64) -> ExprResult with Mut, Panic {
    var a = arena
    let idx = a.count
    a.node_types[idx] = 8
    a.values[idx] = 0.0
    a.left[idx] = child
    a.right[idx] = -1
    a.count = idx + 1
    ExprResult { arena: a, idx: idx }
}

fn expr_exp(arena: ExprArena, child: i64) -> ExprResult with Mut, Panic {
    var a = arena
    let idx = a.count
    a.node_types[idx] = 9
    a.values[idx] = 0.0
    a.left[idx] = child
    a.right[idx] = -1
    a.count = idx + 1
    ExprResult { arena: a, idx: idx }
}

fn expr_log(arena: ExprArena, child: i64) -> ExprResult with Mut, Panic {
    var a = arena
    let idx = a.count
    a.node_types[idx] = 10
    a.values[idx] = 0.0
    a.left[idx] = child
    a.right[idx] = -1
    a.count = idx + 1
    ExprResult { arena: a, idx: idx }
}

fn expr_pow(arena: ExprArena, child: i64, exponent: f64) -> ExprResult with Mut, Panic {
    var a = arena
    let idx = a.count
    a.node_types[idx] = 11
    a.values[idx] = exponent
    a.left[idx] = child
    a.right[idx] = -1
    a.count = idx + 1
    ExprResult { arena: a, idx: idx }
}

// ============================================================================
// EVALUATION
// ============================================================================

fn expr_eval(arena: ExprArena, node_idx: i64, vars: [f64; 16]) -> f64 with Mut, Panic, Div {
    let ntype = arena.node_types[node_idx]

    if ntype == 0 { return arena.values[node_idx] }
    if ntype == 1 {
        let vi = arena.values[node_idx] as i64
        return vars[vi]
    }

    let l = arena.left[node_idx]
    let r = arena.right[node_idx]

    if ntype == 2 {
        return expr_eval(arena, l, vars) + expr_eval(arena, r, vars)
    }
    if ntype == 3 {
        return expr_eval(arena, l, vars) - expr_eval(arena, r, vars)
    }
    if ntype == 4 {
        return expr_eval(arena, l, vars) * expr_eval(arena, r, vars)
    }
    if ntype == 5 {
        return expr_eval(arena, l, vars) / expr_eval(arena, r, vars)
    }
    if ntype == 6 {
        return 0.0 - expr_eval(arena, l, vars)
    }
    if ntype == 7 {
        return sin_f64(expr_eval(arena, l, vars))
    }
    if ntype == 8 {
        return cos_f64(expr_eval(arena, l, vars))
    }
    if ntype == 9 {
        return exp_f64(expr_eval(arena, l, vars))
    }
    if ntype == 10 {
        return ln_f64(expr_eval(arena, l, vars))
    }
    if ntype == 11 {
        let base = expr_eval(arena, l, vars)
        let exp = arena.values[node_idx]
        return pow_f64(base, exp)
    }
    return 0.0
}

// ============================================================================
// SYMBOLIC DIFFERENTIATION
// ============================================================================

fn expr_diff(arena: ExprArena, node_idx: i64, var_idx: i64) -> ExprResult with Mut, Panic, Div {
    let ntype = arena.node_types[node_idx]

    // Const: d/dx(c) = 0
    if ntype == 0 {
        return expr_const(arena, 0.0)
    }

    // Var: d/dx(x) = 1 if same variable, else 0
    if ntype == 1 {
        let vi = arena.values[node_idx] as i64
        if vi == var_idx {
            return expr_const(arena, 1.0)
        }
        return expr_const(arena, 0.0)
    }

    // Add: d/dx(f+g) = df/dx + dg/dx
    if ntype == 2 {
        let l = arena.left[node_idx]
        let r = arena.right[node_idx]
        let dl = expr_diff(arena, l, var_idx)
        let dr = expr_diff(dl.arena, r, var_idx)
        return expr_add(dr.arena, dl.idx, dr.idx)
    }

    // Sub: d/dx(f-g) = df/dx - dg/dx
    if ntype == 3 {
        let l = arena.left[node_idx]
        let r = arena.right[node_idx]
        let dl = expr_diff(arena, l, var_idx)
        let dr = expr_diff(dl.arena, r, var_idx)
        return expr_sub(dr.arena, dl.idx, dr.idx)
    }

    // Mul: d/dx(f*g) = f*dg/dx + df/dx*g  (product rule)
    if ntype == 4 {
        let l = arena.left[node_idx]
        let r = arena.right[node_idx]
        let dl = expr_diff(arena, l, var_idx)
        let dr = expr_diff(dl.arena, r, var_idx)
        // f * dg/dx
        let t1 = expr_mul(dr.arena, l, dr.idx)
        // df/dx * g
        let t2 = expr_mul(t1.arena, dl.idx, r)
        // df/dx*g + f*dg/dx
        return expr_add(t2.arena, t2.idx, t1.idx)
    }

    // Div: d/dx(f/g) = (g*df/dx - f*dg/dx) / g^2  (quotient rule)
    if ntype == 5 {
        let l = arena.left[node_idx]
        let r = arena.right[node_idx]
        let dl = expr_diff(arena, l, var_idx)
        let dr = expr_diff(dl.arena, r, var_idx)
        // g * df/dx
        let t1 = expr_mul(dr.arena, r, dl.idx)
        // f * dg/dx
        let t2 = expr_mul(t1.arena, l, dr.idx)
        // numerator = g*df - f*dg
        let num = expr_sub(t2.arena, t1.idx, t2.idx)
        // g^2
        let g2 = expr_mul(num.arena, r, r)
        return expr_div(g2.arena, num.idx, g2.idx)
    }

    // Neg: d/dx(-f) = -(df/dx)
    if ntype == 6 {
        let child = arena.left[node_idx]
        let dc = expr_diff(arena, child, var_idx)
        return expr_neg(dc.arena, dc.idx)
    }

    // Sin: d/dx(sin(f)) = cos(f) * df/dx
    if ntype == 7 {
        let child = arena.left[node_idx]
        let dc = expr_diff(arena, child, var_idx)
        let cos_f = expr_cos(dc.arena, child)
        return expr_mul(cos_f.arena, cos_f.idx, dc.idx)
    }

    // Cos: d/dx(cos(f)) = -sin(f) * df/dx
    if ntype == 8 {
        let child = arena.left[node_idx]
        let dc = expr_diff(arena, child, var_idx)
        let sin_f = expr_sin(dc.arena, child)
        let neg_sin = expr_neg(sin_f.arena, sin_f.idx)
        return expr_mul(neg_sin.arena, neg_sin.idx, dc.idx)
    }

    // Exp: d/dx(exp(f)) = exp(f) * df/dx
    if ntype == 9 {
        let child = arena.left[node_idx]
        let dc = expr_diff(arena, child, var_idx)
        return expr_mul(dc.arena, node_idx, dc.idx)
    }

    // Log: d/dx(ln(f)) = (1/f) * df/dx
    if ntype == 10 {
        let child = arena.left[node_idx]
        let dc = expr_diff(arena, child, var_idx)
        let one = expr_const(dc.arena, 1.0)
        let inv_f = expr_div(one.arena, one.idx, child)
        return expr_mul(inv_f.arena, inv_f.idx, dc.idx)
    }

    // Pow: d/dx(f^n) = n * f^(n-1) * df/dx
    if ntype == 11 {
        let child = arena.left[node_idx]
        let n = arena.values[node_idx]
        let dc = expr_diff(arena, child, var_idx)
        let n_const = expr_const(dc.arena, n)
        let pow_nm1 = expr_pow(n_const.arena, child, n - 1.0)
        let n_times_pow = expr_mul(pow_nm1.arena, n_const.idx, pow_nm1.idx)
        return expr_mul(n_times_pow.arena, n_times_pow.idx, dc.idx)
    }

    return expr_const(arena, 0.0)
}

// ============================================================================
// SIMPLIFICATION
// ============================================================================

fn is_const_zero(arena: ExprArena, idx: i64) -> bool {
    arena.node_types[idx] == 0 && arena.values[idx] == 0.0
}

fn is_const_one(arena: ExprArena, idx: i64) -> bool {
    arena.node_types[idx] == 0 && arena.values[idx] == 1.0
}

fn expr_simplify(arena: ExprArena, node_idx: i64) -> ExprResult with Mut, Panic, Div {
    let ntype = arena.node_types[node_idx]

    if ntype == 0 { return ExprResult { arena: arena, idx: node_idx } }
    if ntype == 1 { return ExprResult { arena: arena, idx: node_idx } }

    let l = arena.left[node_idx]
    let r = arena.right[node_idx]

    if ntype == 2 {
        if arena.node_types[l] == 0 && arena.node_types[r] == 0 {
            return expr_const(arena, arena.values[l] + arena.values[r])
        }
        if is_const_zero(arena, l) { return ExprResult { arena: arena, idx: r } }
        if is_const_zero(arena, r) { return ExprResult { arena: arena, idx: l } }
        return ExprResult { arena: arena, idx: node_idx }
    }
    if ntype == 3 {
        if arena.node_types[l] == 0 && arena.node_types[r] == 0 {
            return expr_const(arena, arena.values[l] - arena.values[r])
        }
        if is_const_zero(arena, r) { return ExprResult { arena: arena, idx: l } }
        return ExprResult { arena: arena, idx: node_idx }
    }
    if ntype == 4 {
        if arena.node_types[l] == 0 && arena.node_types[r] == 0 {
            return expr_const(arena, arena.values[l] * arena.values[r])
        }
        if is_const_zero(arena, l) { return expr_const(arena, 0.0) }
        if is_const_zero(arena, r) { return expr_const(arena, 0.0) }
        if is_const_one(arena, l) { return ExprResult { arena: arena, idx: r } }
        if is_const_one(arena, r) { return ExprResult { arena: arena, idx: l } }
        return ExprResult { arena: arena, idx: node_idx }
    }
    if ntype == 5 {
        if arena.node_types[l] == 0 && arena.node_types[r] == 0 && arena.values[r] != 0.0 {
            return expr_const(arena, arena.values[l] / arena.values[r])
        }
        if is_const_zero(arena, l) { return expr_const(arena, 0.0) }
        if is_const_one(arena, r) { return ExprResult { arena: arena, idx: l } }
        return ExprResult { arena: arena, idx: node_idx }
    }
    if ntype == 6 {
        if arena.node_types[l] == 0 {
            return expr_const(arena, 0.0 - arena.values[l])
        }
        return ExprResult { arena: arena, idx: node_idx }
    }

    return ExprResult { arena: arena, idx: node_idx }
}

