fn expr_print(arena: ExprArena, node_idx: i64) -> ExprArena with IO, Mut, Panic, Div {
    let ntype = arena.node_types[node_idx]

    if ntype == 0 {
        print(arena.values[node_idx])
        return arena
    }
    if ntype == 1 {
        let vi = arena.values[node_idx] as i64
        if vi == 0 { print("x") }
        else if vi == 1 { print("y") }
        else if vi == 2 { print("z") }
        else { print("v"); print(vi) }
        return arena
    }
    if ntype == 2 {
        print("(")
        let a2 = expr_print(arena, arena.left[node_idx])
        print(" + ")
        let a3 = expr_print(a2, arena.right[node_idx])
        print(")")
        return a3
    }
    if ntype == 3 {
        print("(")
        let a2 = expr_print(arena, arena.left[node_idx])
        print(" - ")
        let a3 = expr_print(a2, arena.right[node_idx])
        print(")")
        return a3
    }
    if ntype == 4 {
        print("(")
        let a2 = expr_print(arena, arena.left[node_idx])
        print(" * ")
        let a3 = expr_print(a2, arena.right[node_idx])
        print(")")
        return a3
    }
    if ntype == 5 {
        print("(")
        let a2 = expr_print(arena, arena.left[node_idx])
        print(" / ")
        let a3 = expr_print(a2, arena.right[node_idx])
        print(")")
        return a3
    }
    if ntype == 6 {
        print("(-")
        let a2 = expr_print(arena, arena.left[node_idx])
        print(")")
        return a2
    }
    if ntype == 7 {
        print("sin(")
        let a2 = expr_print(arena, arena.left[node_idx])
        print(")")
        return a2
    }
    if ntype == 8 {
        print("cos(")
        let a2 = expr_print(arena, arena.left[node_idx])
        print(")")
        return a2
    }
    if ntype == 9 {
        print("exp(")
        let a2 = expr_print(arena, arena.left[node_idx])
        print(")")
        return a2
    }
    if ntype == 10 {
        print("ln(")
        let a2 = expr_print(arena, arena.left[node_idx])
        print(")")
        return a2
    }
    if ntype == 11 {
        print("(")
        let a2 = expr_print(arena, arena.left[node_idx])
        print("^")
        print(arena.values[node_idx])
        print(")")
        return a2
    }
    print("?")
    return arena
}

