fn TAG_CONST() -> i64 { 0 }
fn TAG_VAR() -> i64 { 1 }
fn TAG_ADD() -> i64 { 2 }
fn TAG_SUB() -> i64 { 3 }
fn TAG_MUL() -> i64 { 4 }
fn TAG_DIV() -> i64 { 5 }
fn TAG_NEG() -> i64 { 6 }
fn TAG_SIN() -> i64 { 7 }
