// =============================================================================
// Expression Arena
// =============================================================================

struct ExprArena {
    tags: [i64; 256],
    left: [i64; 256],
    right: [i64; 256],
    values: [f64; 256],
    var_ids: [i64; 256],
    count: i64,
}

fn arena_new() -> ExprArena {
    ExprArena {
        tags: [0; 256],
        left: [0; 256],
        right: [0; 256],
        values: [0.0; 256],
        var_ids: [0; 256],
        count: 0,
    }
}

